65:   trianglesToSTL(triangles, solidName = 'CLEJS_Model') {
66:     let stl = `solid ${solidName}\n`;
67:     const numTriangles = triangles.length / 9;
68:     for (let i = 0; i < numTriangles; i++) {
69:       const idx = i * 9;
70:       const ax = triangles[idx], ay = triangles[idx+1], az = triangles[idx+2];
71:       const bx = triangles[idx+3], by = triangles[idx+4], bz = triangles[idx+5];
72:       const cx = triangles[idx+6], cy = triangles[idx+7], cz = triangles[idx+8];
73: 
74:       const u1 = bx - ax, u2 = by - ay, u3 = bz - az;
75:       const v1 = cx - ax, v2 = cy - ay, v3 = cz - az;
76:       const nx = u2 * v3 - u3 * v2;
77:       const ny = u3 * v1 - u1 * v3;
78:       const nz = u1 * v2 - u2 * v1;
79:       const len = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;
80: 
81:       stl += `  facet normal ${nx/len} ${ny/len} ${nz/len}\n`;
82:       stl += '    outer loop\n';
83:       stl += `      vertex ${ax} ${ay} ${az}\n`;
84:       stl += `      vertex ${bx} ${by} ${bz}\n`;
85:       stl += `      vertex ${cx} ${cy} ${cz}\n`;
86:       stl += '    endloop\n';
87:       stl += '  endfacet\n';
88:     }
89:     stl += `endsolid ${solidName}\n`;
90:     return stl;
91:   }
