254:         `M3 S${tool.spindleRPM} ; 8. Spin up Spindle`,
255:         `G4 P${ts.spindleSpinupDwellSec} ; 9. Dwell for full RPM`,
256:         `; --- Tool T${tool.number} Armed & Ready ---`
257:       ].join('\n');
258:     }
259: 
