96:   trianglesToSTL(triangles, solidName = 'CLEJS_Model') {
97:     let stl = `solid ${solidName}\n`;
98:     const numTriangles = Math.floor(triangles.length / 9);
99:     for (let i = 0; i < numTriangles; i++) {
100:       const idx = i * 9;
101:       const ax = triangles[idx], ay = triangles[idx+1], az = triangles[idx+2];
102:       const bx = triangles[idx+3], by = triangles[idx+4], bz = triangles[idx+5];
103:       const cx = triangles[idx+6], cy = triangles[idx+7], cz = triangles[idx+8];
104: 
105:       const u1 = bx - ax, u2 = by - ay, u3 = bz - az;
106:       const v1 = cx - ax, v2 = cy - ay, v3 = cz - az;
107:       const nx = u2 * v3 - u3 * v2;
108:       const ny = u3 * v1 - u1 * v3;
109:       const nz = u1 * v2 - u2 * v1;
110:       const len = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;
111: 
112:       stl += `  facet normal ${nx/len} ${ny/len} ${nz/len}\n`;
113:       stl += '    outer loop\n';
114:       stl += `      vertex ${ax} ${ay} ${az}\n`;
115:       stl += `      vertex ${bx} ${by} ${bz}\n`;
116:       stl += `      vertex ${cx} ${cy} ${cz}\n`;
117:       stl += '    endloop\n';
118:       stl += '  endfacet\n';
119:     }
120:     stl += `endsolid ${solidName}\n`;
121:     return stl;
122:   }
